using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;
using Mastercam.Database;
using Mastercam.IO;
using Mastercam.Support;
using Mastercam.Operations;
using PorscheAdvanced2027;
using W=Workshop2027;
namespace MastercamPluginAI;
public static class WorkshopBindings
{
    static readonly JsonSerializerOptions Json=new(){IncludeFields=true,Converters={new JsonStringEnumConverter()}};
    internal static string Encode(object x)=>JsonSerializer.Serialize(x,Json);
    static int I(JsonElement e,string k)=>e.GetProperty(k).GetInt32();
    static double N(JsonElement e,string k)=>e.GetProperty(k).GetDouble();
    static string S(JsonElement e,string k)=>e.GetProperty(k).GetString();
    static int[] Ids(JsonElement e,string k)=>e.GetProperty(k).EnumerateArray().Select(x=>x.GetInt32()).ToArray();
    static double? Optional(JsonElement e,string k)=>e.GetProperty(k).ValueKind==JsonValueKind.Null?null:N(e,k);
    static Mastercam.Math.Point3D Point(JsonElement e)=>new(N(e,"x"),N(e,"y"),N(e,"z"));
    static Operation Op(int id)=>SearchManager.GetOperation(id)??throw new ArgumentException("Missing operation: "+id);
    static MCView Plane(int id)=>SearchManager.GetViews().Single(v=>v.ViewID==id);
    static void Require2D(int[] ids){foreach(int id in ids){var o=Op(id);if(o.Locked||o is not ContourOperation&&o is not PocketOperation&&o is not FacingOperation)throw new ArgumentException("Unlocked supported 2D operation required: "+id);}}
    internal static Group[] Groups(){var list=new List<Group>();GroupManager.GetAllGroups(list,false);return list.ToArray();}
    internal static object Context()=>new{active_machine_group=GroupManager.GetActiveMachineGroup()?.ID,active_group=GroupManager.GetActiveGroup()?.ID,groups=Groups().Select(g=>new{g.ID,g.Name,toolpath=g.IsToolpathGroup()}),stock_anchor_values=Enum.GetNames<StockOriginPosition>()};
    static object State(int id){var o=Op(id);return new{id,o.TimeStamp,o.Name,o.GroupNumber,o.Posting,o.Dirty,o.Locked,o.FeedRate,o.PlungeRate,o.RetractRate,o.SpindleSpeed,slot=o.OperationTool?.Slot,o.LengthOffset,o.DiameterOffset,wcs=o.WCS.ViewID,cp=o.ConstructionPlane.ViewID,tp=o.ToolPlane.ViewID,o.UseWCS,o.UseConstructionPlane,o.UseToolPlane,cut=o is ContourOperation c?(object)c.CutParams:o is PocketOperation p?p.CutParams:o is FacingOperation f?f.CutParams:null,link=o is ContourOperation cl?(object)cl.Linking:o is PocketOperation pl?pl.Linking:o is FacingOperation fl?fl.Linking:null};}
    static string States(int[] ids)=>Encode(ids.Select(State));
    static void Select(int[] ids){OperationsManager.UnSelectAllOperations();if(ids.Length>0)OperationsManager.SelectOperations(ids.Select(Op).ToArray());if(!SearchManager.GetOperationIDs(false).Order().SequenceEqual(ids.Order()))throw new InvalidOperationException("Operation selection mismatch.");}
    static void WriteParameters(int id,double? feed,double? spindle,double? wall,double? floor){var o=Op(id);if(feed!=null)o.FeedRate=feed.Value;if(spindle!=null)o.SpindleSpeed=checked((int)spindle.Value);switch(o){case ContourOperation c:if(wall!=null)c.CutParams.LeaveStock.OnWalls=wall.Value;if(floor!=null)c.CutParams.LeaveStock.OnFloors=floor.Value;break;case PocketOperation p:if(wall!=null)p.CutParams.LeaveStock.OnWalls=wall.Value;if(floor!=null)p.CutParams.LeaveStock.OnFloors=floor.Value;break;case FacingOperation f:if(wall!=null)f.CutParams.LeaveStock.OnWalls=wall.Value;if(floor!=null)f.CutParams.LeaveStock.OnFloors=floor.Value;break;}o.MarkDirty();if(!o.Commit(false))throw new InvalidOperationException("Parameter Commit failed.");var r=W.Work.ReadParameters(new[]{id})[0];bool Equal(double? a,double? b)=>a==null||b!=null&&Math.Abs(a.Value-b.Value)<1e-8;if(!Equal(feed,r.Feed)||!Equal(spindle,r.Spindle)||!Equal(wall,r.Wall)||!Equal(floor,r.Floor)||!r.Dirty)throw new InvalidOperationException("Parameter fresh readback mismatch.");}
    public static PorscheBinding Prepare(JsonElement q,string directory)
    {
        var c=q.GetProperty("parameters");string action=S(q,"action");var b=new PorscheBinding();
        if(action=="operation.parameters"){
            var ids=Ids(q,"operation_ids");Require2D(ids);var before=W.Work.ReadParameters(ids);double? feed=Optional(c,"feed"),rpm=Optional(c,"spindle"),wall=Optional(c,"wall"),floor=Optional(c,"floor");if(rpm!=null&&before.Any(x=>x.Css))throw new ArgumentException("RPM cannot be applied to CSS operation.");string after=null;
            b.Preview=new{action,before,parameters=c,regenerates=false};
            void Restore(){foreach(var x in before)WriteParameters(x.Id,x.Feed,x.Spindle,x.Wall,x.Floor);}
            b.Apply=()=>{try{foreach(int id in ids)WriteParameters(id,feed,rpm,wall,floor);after=States(ids);}catch{Restore();throw;}};
            b.Rollback=()=>{if(States(ids)!=after)throw new InvalidOperationException("Operation changed after parameters apply.");Restore();};b.Readback=()=>W.Work.ReadParameters(ids);
        }else if(action=="operation.planes"){
            var ids=Ids(q,"operation_ids");Require2D(ids);var target=Plane(I(c,"plane_id"));
            var before=ids.Select(Op).Select(o=>new{id=o.GetOperationID(),wcs=o.WCS.ViewID,cp=o.ConstructionPlane.ViewID,tp=o.ToolPlane.ViewID,o.UseWCS,o.UseConstructionPlane,o.UseToolPlane}).ToArray();string after=null;
            void Set(int id,int w,int cp,int t,bool uw,bool uc,bool ut){var o=Op(id);o.WCS=Plane(w);o.ConstructionPlane=Plane(cp);o.ToolPlane=Plane(t);o.UseWCS=uw;o.UseConstructionPlane=uc;o.UseToolPlane=ut;o.MarkDirty();if(!o.Commit(false))throw new InvalidOperationException("Plane commit failed.");o=Op(id);if(o.WCS.ViewID!=w||o.ConstructionPlane.ViewID!=cp||o.ToolPlane.ViewID!=t||o.UseWCS!=uw||o.UseConstructionPlane!=uc||o.UseToolPlane!=ut)throw new InvalidOperationException("Plane fresh readback mismatch.");}
            void Restore(){foreach(var x in before)Set(x.id,x.wcs,x.cp,x.tp,x.UseWCS,x.UseConstructionPlane,x.UseToolPlane);}
            b.Preview=new{action,before,plane_id=target.ViewID,frame=HoleHost.PlaneState(target),regenerates=false};b.Apply=()=>{try{foreach(int id in ids)Set(id,target.ViewID,target.ViewID,target.ViewID,true,true,true);after=States(ids);}catch{Restore();throw;}};b.Rollback=()=>{if(after!=States(ids))throw new InvalidOperationException("Operation changed after planes apply.");Restore();};b.Readback=()=>ids.Select(State).ToArray();
        }else if(action=="operation.copy"){
            int[] ids=Ids(q,"operation_ids");int target=I(c,"target_group_id");var group=GroupManager.FindGroupByID(target)??throw new ArgumentException("Missing target group.");if(!group.IsToolpathGroup())throw new ArgumentException("Toolpath target group required.");int machine=GroupManager.GetActiveMachineGroup().ID;var ancestor=group;var seen=new HashSet<int>();while(ancestor!=null&&!ancestor.IsMachineGroup()){if(!seen.Add(ancestor.ID))throw new InvalidOperationException("Cyclic group tree.");ancestor=ancestor.GetParentGroup();}if(ancestor?.ID!=machine)throw new ArgumentException("Target must belong to the active machine group.");
            foreach(int id in ids)if(Op(id).Locked||Op(id) is not ContourOperation&&Op(id) is not DrillOperation||SearchManager.GetOperationData(id).MachineGroupID!=machine)throw new ArgumentException("Copy currently accepts unlocked contour/drill sources in active machine group.");
            var baseline=SearchManager.GetOperationIDs(true);var source=ids.Select(HoleHost.OperationState).ToArray();var created=new List<int>();Dictionary<int,string> after=null;int[] selection=SearchManager.GetOperationIDs(false);
            void Delete(){foreach(int id in created.AsEnumerable().Reverse()){var o=SearchManager.GetOperation(id);if(o!=null&&(baseline.Contains(id)||!o.Delete()))throw new InvalidOperationException("Owned copy deletion failed.");}Select(selection);OperationsManager.InitOperationsManagerTree();}
            b.Preview=new{action,source_ids=ids,target_group_id=target,group_name=group.Name,source,posting=false,regenerates=false};
            b.Apply=()=>{try{foreach(int id in ids){var prior=SearchManager.GetOperationIDs(true);int copied=OperationsManager.CopyOperation(Op(id),group);var added=SearchManager.GetOperationIDs(true).Except(prior).ToArray();if(copied>0&&!baseline.Contains(copied))created.Add(copied);if(copied<=0||!added.SequenceEqual(new[]{copied}))throw new InvalidOperationException("Unexpected copy allocation; inspect database.");var fresh=Op(copied);fresh.Posting=false;fresh.MarkDirty();if(!fresh.Commit(false)||Op(copied).Posting||Op(copied).GroupNumber!=target)throw new InvalidOperationException("Copy parameter/group readback failed.");}if(!source.SequenceEqual(ids.Select(HoleHost.OperationState)))throw new InvalidOperationException("Copy changed source operations.");after=created.ToDictionary(id=>id,HoleHost.OperationState);}catch{Delete();throw;}finally{Select(selection);OperationsManager.InitOperationsManagerTree();}};
            b.Rollback=()=>{foreach(var x in after)if(x.Value!=HoleHost.OperationState(x.Key))throw new InvalidOperationException("Copied operation changed; rollback refused.");Delete();};b.Readback=()=>new{created_ids=created,operations=created.Select(id=>new{id,exists=SearchManager.GetOperationData(id)?.IsValid==true,state=SearchManager.GetOperationData(id)?.IsValid==true?HoleHost.OperationState(id):null}),source_preserved=source.SequenceEqual(ids.Select(HoleHost.OperationState))};
        }else if(action=="groups.create"){
            int parent=I(c,"parent_id");string prefix=S(c,"prefix");int start=I(c,"start"),count=I(c,"count");var p=GroupManager.FindGroupByID(parent)??throw new ArgumentException("Missing parent.");var expected=Enumerable.Range(start,count).Select(i=>prefix+i.ToString("D2")).ToArray();foreach(var name in expected)if(GroupManager.FindGroupByName(name)!=null)throw new ArgumentException("Existing group: "+name);int[] owned=Array.Empty<int>();int active=GroupManager.GetActiveGroup()?.ID??throw new InvalidOperationException("Active group required.");if(parent!=active)throw new ArgumentException("Parent must be the current active group; this API does not reposition the insertion arrow.");
            b.Preview=new{action,parent_id=parent,p.Name,names=expected,original_active_group=active};b.Apply=()=>owned=W.Work.CreateGroups(parent,prefix,start,count);b.Rollback=()=>{for(int i=0;i<owned.Length;i++){var g=GroupManager.FindGroupByID(owned[i]);if(g==null||g.Name!=expected[i]||g.GetParentGroup()?.ID!=parent||Groups().Any(child=>child.GetParentGroup()?.ID==g.ID)||SearchManager.GetOperations().Any(o=>o.GroupNumber==g.ID))throw new InvalidOperationException("Created group changed or contains operations.");}foreach(int id in owned.Reverse()){var g=GroupManager.FindGroupByID(id);GroupManager.DeleteGroup(ref g);if(GroupManager.FindGroupByID(id)!=null)throw new InvalidOperationException("Group deletion failed.");}OperationsManager.InitOperationsManagerTree();};b.Readback=()=>new{created_ids=owned,groups=owned.Select(id=>new{id,name=GroupManager.FindGroupByID(id)?.Name})};
        }else if(action=="groups.rename"){
            var items=c.GetProperty("names").EnumerateArray().Select(e=>new{id=I(e,"group_id"),name=S(e,"name")}).ToArray();var before=items.Select(x=>new{x.id,name=GroupManager.FindGroupByID(x.id)?.Name??throw new ArgumentException("Missing group")}).ToArray();var occupied=Groups().Where(g=>!items.Any(x=>x.id==g.ID)).Select(g=>g.Name).ToArray();if(items.Any(x=>occupied.Contains(x.name,StringComparer.OrdinalIgnoreCase))||items.Select(x=>x.name).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=items.Length)throw new ArgumentException("Group name collision.");
            void Set(int id,string name){var g=GroupManager.FindGroupByID(id);g.Name=name;if(GroupManager.FindGroupByID(id)?.Name!=name)throw new InvalidOperationException("Group name readback mismatch.");}
            void Restore(){if(Groups().Any(g=>!before.Any(x=>x.id==g.ID)&&before.Any(x=>string.Equals(x.name,g.Name,StringComparison.OrdinalIgnoreCase))))throw new InvalidOperationException("Original group name is now occupied.");foreach(var x in before)Set(x.id,"AI_RESTORE_"+Guid.NewGuid().ToString("N"));foreach(var x in before)Set(x.id,x.name);}
            b.Preview=new{action,before,after=items};b.Apply=()=>{try{foreach(var x in items)Set(x.id,"AI_RENAME_"+Guid.NewGuid().ToString("N"));foreach(var x in items)Set(x.id,x.name);}catch{Restore();throw;}};b.Rollback=()=>{foreach(var x in items)if(GroupManager.FindGroupByID(x.id)?.Name!=x.name)throw new InvalidOperationException("Group renamed since apply.");Restore();};b.Readback=()=>items.Select(x=>new{x.id,name=GroupManager.FindGroupByID(x.id)?.Name}).ToArray();
        }else if(action=="stock.rectangle"){
            int group=I(c,"machine_group_id");var before=W.Workflow.CloneStock(MillStock.GetStockData(group)??throw new ArgumentException("Missing milling stock."));string original=Encode(before),after=null;var anchor=Enum.Parse<StockOriginPosition>(S(c,"anchor"));var size=Point(c.GetProperty("size"));var origin=Point(c.GetProperty("origin"));int plane=I(c,"plane_id");
            b.Preview=new{action,machine_group_id=group,before,parameters=c};b.Apply=()=>{W.Workflow.SetRectangularStock(group,size,origin,anchor,checked((short)plane));after=Encode(MillStock.GetStockData(group));};b.Rollback=()=>{if(Encode(MillStock.GetStockData(group))!=after)throw new InvalidOperationException("Stock changed after apply.");if(!MillStock.SetStockData(before,group)||Encode(MillStock.GetStockData(group))!=original)throw new InvalidOperationException("Stock restoration mismatch.");};b.Readback=()=>MillStock.GetStockData(group);
        }else if(action=="view.planes"){
            var oldW=ViewManager.WorkCoordinateSystem;var oldC=ViewManager.CPlane;var oldT=ViewManager.TPlane;var oldG=ViewManager.GraphicsView;bool cg=ViewManager.CplaneFollowsGplane,cw=ViewManager.CplaneFollowsWcs,gw=ViewManager.GplaneFollowsWcs;string after=null;
            var w=Plane(I(c,"wcs_id"));var cp=Plane(I(c,"construction_id"));var t=Plane(I(c,"tool_id"));var g=Plane(I(c,"graphics_id"));bool ncg=c.GetProperty("cplane_follows_graphics").GetBoolean(),ncw=c.GetProperty("cplane_follows_wcs").GetBoolean(),ngw=c.GetProperty("graphics_follows_wcs").GetBoolean();
            object Current()=>new{wcs=ViewManager.WorkCoordinateSystem.ViewID,construction=ViewManager.CPlane.ViewID,tool=ViewManager.TPlane.ViewID,graphics=ViewManager.GraphicsView.ViewID,ViewManager.CplaneFollowsGplane,ViewManager.CplaneFollowsWcs,ViewManager.GplaneFollowsWcs};
            void Set(MCView sw,MCView sc,MCView st,MCView sg,bool fcg,bool fcw,bool fgw){ViewManager.CplaneFollowsGplane=false;ViewManager.CplaneFollowsWcs=false;ViewManager.GplaneFollowsWcs=false;ViewManager.WorkCoordinateSystem=sw;ViewManager.CPlane=sc;ViewManager.TPlane=st;ViewManager.GraphicsView=sg;ViewManager.CplaneFollowsGplane=fcg;ViewManager.CplaneFollowsWcs=fcw;ViewManager.GplaneFollowsWcs=fgw;if(ViewManager.WorkCoordinateSystem.ViewID!=sw.ViewID||ViewManager.CPlane.ViewID!=sc.ViewID||ViewManager.TPlane.ViewID!=st.ViewID||ViewManager.GraphicsView.ViewID!=sg.ViewID)throw new InvalidOperationException("View plane readback mismatch.");GraphicsManager.Repaint();}
            void Restore()=>Set(oldW,oldC,oldT,oldG,cg,cw,gw);
            b.Preview=new{action,before=Current(),parameters=c};b.Apply=()=>{try{Set(w,cp,t,g,ncg,ncw,ngw);after=Encode(Current());}catch{Restore();throw;}};b.Rollback=()=>{if(Encode(Current())!=after)throw new InvalidOperationException("View changed after apply.");Restore();};b.Readback=Current;
        }else throw new ArgumentException("Unknown workshop action: "+action);
        return b;
    }
}
